+std::vector<unsigned char> read_bytes(void *data, size_t bytes) {
+  std::vector<unsigned char> result(bytes);
+  NVTE_CHECK_CUDA(cudaMemcpy(result.data(), data, bytes, cudaMemcpyDeviceToHost));
+  return result;
+}
