+  ASSERT_EQ(cudaStreamBeginCapture(stream, cudaStreamCaptureModeThreadLocal), cudaSuccess);
+  EXPECT_NO_THROW(nvte_group_quantize_v2(data.input.data(), data.output.data(), workspace.data(),
